private void pop(final String descriptor) {
    char type = descriptor.charAt(0);
    if (type == 'L' || type == '[') {
        // Reference type or array, pop one
        pop();
    } else if (type == 'B' || type == 'C' || type == 'D' || type == 'F' || type == 'I' || type == 'J' || type == 'S' || type == 'Z') {
        // Primitive type, pop one
        pop();
    } else if (type == '(') {
        // Method descriptor, pop parameters
        int count = 1;
        while (descriptor.charAt(count) != ')') {
            count++;
        }
        for (int i = 0; i < count - 1; i++) {
            pop();
        }
    }
}

